38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "postcode")
50	    private String postcode;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    @Email
59	    private String email;
60	
61	    @Column(name = "registration_date", columnDefinition = "DATE")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "birth_date", columnDefinition = "DATE")
65	    private LocalDate birthDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private boolean bulkSignupWarning;
81	
82	    @Column(name = "household_member_count")
83	    private Integer householdMemberCount;
84	
85	    @Column(name = "possible_duplicate")
86	    private boolean possibleDuplicate;
87	
88	    @Column(name = "possible_duplicate_of")
89	    private Integer possibleDuplicateOf;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    /**
95	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
96	     * another owner already shares the same last name and address. Never persisted or returned.
97	     */
98	    @Transient
99	    private boolean sharesHousehold;
100	
101	    public String getAddress() {
102	        return this.address;
103	    }
104	
105	    public void setAddress(String address) {
106	        this.address = address;
107	    }
108	
109	    public String getCity() {
110	        return this.city;
111	    }
112	
113	    public void setCity(String city) {
114	        this.city = city;
115	    }
116	
117	    public String getPostcode() {
118	        return this.postcode;
119	    }
120	
121	    public void setPostcode(String postcode) {
122	        this.postcode = postcode;
123	    }
124	
125	    public String getTelephone() {
126	        return this.telephone;
127	    }
128	
129	    public void setTelephone(String telephone) {
130	        this.telephone = telephone;
131	    }
132	
133	    public String getEmail() {
134	        return this.email;
135	    }
136	
137	    public void setEmail(String email) {
138	        this.email = email;
139	    }
