153	    public void setBirthDate(LocalDate birthDate) {
154	        this.birthDate = birthDate;
155	    }
156	
157	    /**
158	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
159	     * owner's {@code registrationDate} (falling back to the current date when no registration date
160	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
161	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
162	     */
163	    @Transient
164	    public String getAgeBand() {
165	        if (this.birthDate == null) {
166	            return null;
167	        }
168	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
169	        int age = Period.between(this.birthDate, reference).getYears();
170	        if (age < 18) {
171	            return "MINOR";
172	        }
173	        if (age < 65) {
174	            return "ADULT";
175	        }
176	        return "SENIOR";
177	    }
178	
179	    public String getCustomerCode() {
180	        return this.customerCode;
181	    }
182	
183	    public void setCustomerCode(String customerCode) {
184	        this.customerCode = customerCode;
185	    }
186	
187	    public String getMembershipNumber() {
188	        return this.membershipNumber;
189	    }
190	
191	    public void setMembershipNumber(String membershipNumber) {
192	        this.membershipNumber = membershipNumber;
193	    }
