203	    public Integer getNamesakeCount() {
204	        return this.namesakeCount;
205	    }
206	
207	    public void setNamesakeCount(Integer namesakeCount) {
208	        this.namesakeCount = namesakeCount;
209	    }
210	
211	    /**
212	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
213	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
214	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
215	     * the owner's tenure exceeds 365 days (measured from the {@code registrationDate} to today).
216	     */
217	    @Transient
218	    public Integer getMembershipPoints() {
219	        int points = 0;
220	        if (this.email != null && !this.email.isBlank()) {
221	            points += 2;
222	        }
223	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
224	            points += 1;
225	        }
226	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
227	            points += 2;
228	        }
229	        if (hasTenureOver365Days()) {
230	            points += 3;
231	        }
232	        return points;
233	    }
234	
235	    /**
236	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
237	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
238	     * points, and level 4 for 6 or more points.
239	     */
240	    @Transient
241	    public Integer getMembershipLevel() {
242	        int points = getMembershipPoints();
243	        if (points <= 1) {
244	            return 1;
245	        }
246	        if (points <= 3) {
247	            return 2;
248	        }
249	        if (points <= 5) {
250	            return 3;
251	        }
252	        return 4;
253	    }
254	
255	    /**
256	     * Whether the owner's tenure, measured as the number of whole days from {@code registrationDate}
257	     * to today, exceeds 365 days — worth 3 membership points. A missing {@code registrationDate}
258	     * (and therefore zero tenure) never qualifies.
259	     */
260	    @Transient
261	    private boolean hasTenureOver365Days() {
262	        if (this.registrationDate == null) {
263	            return false;
264	        }
265	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
266	    }
267	
268	    /**
269	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
270	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
271	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
272	     * has been assigned yet.
273	     */
274	    @Transient
275	    public Integer getCheckDigit() {
276	        if (this.customerCode == null) {
277	            return null;
278	        }
279	        int sum = 0;
280	        boolean dbl = true;
281	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
282	            char c = this.customerCode.charAt(i);
283	            if (c < '0' || c > '9') {
284	                continue;
285	            }
286	            int d = c - '0';
287	            if (dbl) {
288	                d *= 2;
289	                if (d > 9) {
290	                    d -= 9;
291	                }
292	            }
293	            sum += d;
294	            dbl = !dbl;
295	        }
296	        return (10 - (sum % 10)) % 10;
297	    }
298	
299	    /**
300	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
301	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
302	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
303	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
304	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
305	     */
306	    @Transient
307	    public String getIdentityKey() {
308	        String telephonePart = this.telephone == null ? "" : this.telephone;
309	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
310	        String householdPart = this.householdId == null ? "" : this.householdId;
311	        return telephonePart + "|" + emailPart + "|" + householdPart;
312	    }
313	
314	    public boolean isBulkSignupWarning() {
315	        return this.bulkSignupWarning;
316	    }
317	
318	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
319	        this.bulkSignupWarning = bulkSignupWarning;
320	    }
321	
322	    public Integer getHouseholdMemberCount() {
323	        return this.householdMemberCount;
324	    }
325	
326	    public void setHouseholdMemberCount(Integer householdMemberCount) {
327	        this.householdMemberCount = householdMemberCount;
328	    }
329	
330	    /**
331	     * Whether this owner was flagged at creation as a possible (soft) duplicate: it is not a hard
332	     * {@code identityKey} duplicate, but shares an existing owner's last name and postcode while
333	     * carrying a different telephone. The owner is still created; this flag is advisory.
334	     */
335	    public boolean isPossibleDuplicate() {
336	        return this.possibleDuplicate;
337	    }
338	
339	    public void setPossibleDuplicate(boolean possibleDuplicate) {
340	        this.possibleDuplicate = possibleDuplicate;
341	    }
342	
343	    /**
344	     * The id of the existing owner this one soft-matched against (same last name and postcode,
345	     * different telephone), or {@code null} when {@link #isPossibleDuplicate()} is {@code false}.
346	     */
347	    public Integer getPossibleDuplicateOf() {
348	        return this.possibleDuplicateOf;
349	    }
350	
351	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
352	        this.possibleDuplicateOf = possibleDuplicateOf;
353	    }
354	
355	    public boolean isSharesHousehold() {
356	        return this.sharesHousehold;
357	    }
358	
359	    public void setSharesHousehold(boolean sharesHousehold) {
360	        this.sharesHousehold = sharesHousehold;
361	    }
362	
363	    protected Set<Pet> getPetsInternal() {
364	        if (this.pets == null) {
365	            this.pets = new HashSet<>();
366	        }
367	        return this.pets;
368	    }
369	
370	    protected void setPetsInternal(Set<Pet> pets) {
371	        this.pets = pets;
372	    }
373	
374	    public List<Pet> getPets() {
375	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
376	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
377	        return Collections.unmodifiableList(sortedPets);
378	    }
379	
380	    public void setPets(List<Pet> pets) {
381	        this.pets = new HashSet<>(pets);
382	    }
383	
384	    public void addPet(Pet pet) {
385	        getPetsInternal().add(pet);
386	        pet.setOwner(this);
387	    }
388	
389	    /**
390	     * Return the Pet with the given name, or null if none found for this Owner.
391	     *
392	     * @param name to test
393	     * @return true if pet name is already in use
394	     */
395	    public Pet getPet(String name) {
396	        return getPet(name, false);
397	    }
398	
399	    /**
400	     * Return the Pet with the given name, or null if none found for this Owner.
401	     *
402	     * @param name to test
403	     * @return true if pet name is already in use
404	     */
405	    public Pet getPet(String name, boolean ignoreNew) {
406	        name = name.toLowerCase();
407	        for (Pet pet : getPetsInternal()) {
408	            if (!ignoreNew || !pet.isNew()) {
409	                String compName = pet.getName();
410	                compName = compName.toLowerCase();
411	                if (compName.equals(name)) {
412	                    return pet;
413	                }
414	            }
415	        }
416	        return null;
417	    }
418	
419	    public Pet getPet(Integer petId) {
420	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
421	    }
422	
423	    @Override
424	    public String toString() {
425	        return new ToStringCreator(this)
426	
427	            .append("id", this.getId())
428	            .append("new", this.isNew())
429	            .append("lastName", this.getLastName())
430	            .append("firstName", this.getFirstName())
431	            .append("address", this.address)
432	            .append("city", this.city)
433	            .append("telephone", this.telephone)
434	            .toString();
435	    }
436	}
